+/// Names resolved for a query and their immediate callers/callees.
+pub(crate) struct QuerySymbols {
+    pub direct: BTreeSet<(String, String)>,
+    pub related: BTreeSet<(String, String)>,
+}
+
+/// Resolve every explicit query name for symbol-linked memory priority.
+/// An absent, ambiguous, changed, inaccessible or unreadable definition leaves
+/// the existing window-based order in place. Reuse the identifier route's
+/// names (without component-name expansion) and this arm's definition resolver.
+pub(crate) fn query_symbols(
+    db: &Connection,
+    repository: &str,
+    question: &str,
+    documents: &HashMap<&str, &Value>,
+) -> Option<QuerySymbols> {
+    use crate::identifier_route::{Shape, classify};
+    let names = match classify(question) {
+        Shape::Lookup(names) | Shape::AsksMore(names) => names,
+        Shape::PlainWords => return None,
+    };
+    if names.len() > MAX_NAMES {
+        return None;
+    }
+    let paths = named(question).paths;
+    let graph = code_graph(db, repository, true)?;
+    // Do not rank with relationships from an older episode.
+    if graph.unchanged.is_some() {
+        return None;
+    }
+    let mut selected = BTreeSet::new();
+    let mut related = BTreeSet::new();
+    for name in names {
+        let found: Vec<usize> = graph
+            .definitions(&name)
+            .into_iter()
+            .filter(|&i| {
+                let (_, path) = graph.symbol(i);
+                paths.is_empty()
+                    || paths
+                        .iter()
+                        .any(|named| path == named || path.ends_with(&format!("/{named}")))
+            })
+            .collect();
+        let [index] = found.as_slice() else {
+            return None;
+        };
+        let (qualified, path) = graph.symbol(*index);
+        if !documents.contains_key(format!("file:{path}").as_str())
+            || graph
+                .unchanged
+                .as_ref()
+                .is_some_and(|unchanged| !unchanged.contains(path))
+        {
+            return None;
+        }
+        selected.insert((path.to_string(), qualified.to_string()));
+        related.extend(graph.call_neighbours(*index, documents)?);
+    }
+    related.retain(|symbol| !selected.contains(symbol));
+    (!graph.corrupt() && !selected.is_empty()).then_some(QuerySymbols {
+        direct: selected,
+        related,
+    })
 }

