+fn callers_and_callees_share_capacity_with_direct_notes() {
+    for (target, dependency) in [
+        ("send_packet", "backoff_delay"),
+        ("backoff_delay", "send_packet"),
+    ] {
+        let f = Fixture::new(&[(
+            "pipeline.py",
+            "def backoff_delay(attempt):\n    return min(2 ** attempt, 60)\n\ndef send_packet(attempt):\n    return backoff_delay(attempt)\n",
+        )]);
+        let peer = f.note(
+            "Peer lifetime",
+            "The remote session expires after one minute.",
+            json!([{"path":"pipeline.py","qualified_name":dependency}]),
+        );
+        for title in [
+            "Quokka ledger",
+            "Wombat archive",
+            "Orchid protocol",
+            "Cedar sampling",
+        ] {
+            f.note(
+                title,
+                "Preserve the original fiscal records.",
+                json!([{"path":"pipeline.py","qualified_name":target}]),
+            );
+        }
+        let packet = f.context(
+            &format!("Why does {target} cap the backoff at sixty seconds?"),
+            json!({"symbol_links":true,"identifier_route":false,"notes_first":false}),
+        );
+        assert!(includes(&packet, &peer), "{packet:#}");
+        assert_eq!(packet["symbol_links"]["lifted_memories"], 4, "{packet:#}");
+        assert_eq!(packet["symbol_links"]["over_limit"], 1, "{packet:#}");
+    }
+}
