+    let code = (0..6)
+        .map(|i| format!("def stage_{i}():\n    return {i}\n\n"))
+        .collect::<String>();
+    let f = Fixture::new(&[("pipeline.py", &code)]);
+    for i in 0..5 {
+        f.note(
+            [
+                "Quokka ledger",
+                "Wombat archive",
+                "Orchid protocol",
+                "Cedar sampling",
+                "Peer lifetime",
+                "Violet ordering",
+            ][i],
+            "Preserve the original fiscal records.",
+            json!([{"path":"pipeline.py","qualified_name":format!("stage_{i}")}]),
+        );
+    }
+    let shared = f.note(
+        "Amber registry",
+        "Retain a durable audit receipt.",
+        json!([{"path":"pipeline.py","qualified_name":"stage_0"},
+               {"path":"pipeline.py","qualified_name":"stage_5"}]),
+    );
+    let packet = f.context(
+        "Which constraint applies to stage_5?",
+        json!({"symbol_links":true,"identifier_route":false,"notes_first":false}),
+    );
+    assert!(includes(&packet, &shared), "{packet:#}");
+    assert_eq!(packet["symbol_links"]["lifted_memories"], 4, "{packet:#}");
+    assert_eq!(packet["symbol_links"]["over_limit"], 2, "{packet:#}");
